5|import type { AgentRuntimeEvent } from './runtimeEvents';
6|import type { AgentToolIdempotency } from './operationalPolicyEngine';
7|
8|/**
9| * V5 Phase P01 § 4.3 — `OperationalState`.
10| *
11| * Scoped to what `AgentOrchestrator` can populate for real today (iteration/token/retrieval/draft
12| * counters that previously lived only as local `run()` variables — see `PHASE-01-...md` § 4.1 —
13| * plus failure-signature tracking, which is new). The full canonical shape in the phase doc also
14| * includes `taskContract`, `activeHypotheses`, `patch`, `workspace`, `acceptance`, `risk`, `budget`,
15| * `health` — those require `TaskContract`/`Evidence`/`PatchIntent`/`Verification` types that don't
16| * exist until Phases 02/06/07, so they're deferred (see PHASE-EVIDENCE-REPORT-P01.md § Remaining).
17| */
18|export type AgentPhase = 'EXPLORE' | 'PLAN' | 'EDIT' | 'VERIFY' | 'COMPLETE' | 'BLOCKED' | 'FAILED';
19|export type TaskOutcomeState = 'IN_PROGRESS' | 'COMPLETED' | 'FAILED' | 'BLOCKED' | 'ABSTAINED';
20|
21|export type FailureSignatureRef = {
22|  /** `${toolName}:${normalizedTarget}` — coarser than exact-args-hash repetition (orchestrationPolicy.ts). */
23|  signature: string;
24|  toolName: string;
25|  target: string;
26|  occurrences: number;
27|  lastError?: string;
28|  /** Set once a VERIFY-class tool (run_tests/test_server_function) succeeds after this signature. */
29|  recoveredAt?: string;
30|};
31|
32|/** V5 Phase P09 § V5-13 — a tool call whose ToolExecutionStarted has no matching resolution. */
33|export type PendingUnknownOutcome = {
34|  toolName: string;
35|  target: string;
36|  idempotency: AgentToolIdempotency;
37|  detectedAt: string;
38|};
39|
40|export interface OperationalState {
41|  taskId: string;
42|  attemptId: string;
43|  phase: AgentPhase;
44|  outcomeState: TaskOutcomeState;
45|  iteration: number;
46|  retrievalOperationCount: number;
47|  draftToolCount: number;
48|  tokensEstimate: number;
49|  failureSignatures: FailureSignatureRef[];
50|  clarificationPending: boolean;
51|  stallDetected: boolean;
52|  lastEventSequence: number;
53|  updatedAt: string;
54|  pendingUnknownOutcomes: PendingUnknownOutcome[];
55|}
56|
57|export const createInitialOperationalState = (taskId: string, attemptId: string): OperationalState => ({
58|  taskId,
59|  attemptId,
60|  phase: 'EXPLORE',
61|  outcomeState: 'IN_PROGRESS',
62|  iteration: 0,
63|  retrievalOperationCount: 0,
64|  draftToolCount: 0,
65|  tokensEstimate: 0,
66|  failureSignatures: [],
67|  clarificationPending: false,
68|  stallDetected: false,
69|  lastEventSequence: 0,
70|  updatedAt: new Date(0).toISOString(),
71|  pendingUnknownOutcomes: [],
72|});
73|
74|const VERIFY_TOOL_NAMES = new Set(['run_tests', 'test_server_function']);
75|
76|const clearPendingUnknownOutcome = (
77|  pending: PendingUnknownOutcome[],
78|  toolName: string,
79|  target: string | undefined,
80|): PendingUnknownOutcome[] => (
81|  pending.some((entry) => entry.toolName === toolName && entry.target === target)
82|    ? pending.filter((entry) => !(entry.toolName === toolName && entry.target === target))
83|    : pending
84|);
85|
86|const withSignature = (
87|  signatures: FailureSignatureRef[],
88|  signature: string,
89|  mutate: (existing: FailureSignatureRef | undefined) => FailureSignatureRef,
90|): FailureSignatureRef[] => {
91|  const idx = signatures.findIndex((entry) => entry.signature === signature);
92|  const next = mutate(idx >= 0 ? signatures[idx] : undefined);
93|  if (idx >= 0) {
94|    const copy = [...signatures];
95|    copy[idx] = next;
96|    return copy;
97|  }
98|  return [...signatures, next];
99|};
100|
101|/**
102| * Pure reducer: `(state, event) => nextState`. Deterministic given a deterministic event stream —
103| * see `hashOperationalState` for what "deterministic" means here (state transitions, not raw
104| * model text — model responses are inherently non-deterministic even against the same prompt).
105| */
106|export const reduceOperationalState = (
107|  state: OperationalState,
108|  event: AgentRuntimeEvent,
109|): OperationalState => {
110|  const base: OperationalState = { ...state, lastEventSequence: event.sequence, updatedAt: event.createdAt };
111|
112|  switch (event.type) {
113|    case 'TaskCreated':
114|      return base;
115|
116|    case 'ProgressRecorded': {
117|      const payload = event.payload as { iteration: number; tokensEstimate: number };
118|      return { ...base, iteration: payload.iteration, tokensEstimate: payload.tokensEstimate };
119|    }
120|"
